import {openingPrice,quotePricing} from './quote-pricing.js';
import {productId,supportsCutSheets,CUT_SHEETS_ONLY} from './products.js';
import {parseMeasurement,measurementInput} from './measurements.js';
import {cutSheetFacts,cutSheetNotes,louverSummary,machiningLabel} from './cut-sheet.js';
import {shopRequest} from './shop-client.js';
import {loadLogo,saveLogo,readLogoFile} from './branding.js';
import {FRAME_STYLES,frameStyle,frameNotice,frameThumbnail} from './frames.js';
import {STANDARD_LAYOUTS,TPOST_LAYOUTS,drawingSVG} from './layouts.js';
const $=s=>document.querySelector(s), h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={jobs:'M4 7h16v13H4z M8 7V4h8v3 M4 11h16',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',check:'M5 12l4 4L19 6',copy:'M9 9h12v12H9z M15 5V3H3v12h2',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',arrow:'M4 12h16 M14 6l6 6-6 6',info:'M12 8h.01 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',ruler:'M3 7h18v10H3z M7 7v4 M11 7v3 M15 7v4 M19 7v3',panels:'M3 3h18v18H3z M12 3v18 M5 7h5 M14 7h5 M5 11h5 M14 11h5 M5 15h5 M14 15h5',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',close:'M6 6l12 12 M18 6L6 18',back:'M20 12H4 M10 6l-6 6 6 6',archive:'M3 3h18v5H3z M5 8v13h14V8 M9 12h6',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const FRAMES={ST:'Standard frame',DS:'Designer frame',EX:'Extended frame',ZF:'Z-frame',TR:'Trim frame',HS:'Hanging strip'},COLORS={W:'White',OW:'Off-white',SC:'Swiss coffee'};
const KEY='shutter-factory-workshop-v1',uid=()=>crypto.randomUUID();
const newOpening=(name='New opening')=>({id:uid(),name,width:36,height:60,quantity:1,left:1,right:1,louver:4,frame:'ST',sides:'4W',mount:'I',sizeMethod:'S',color:'W',tilt:'Smart',stile:'Flat',divider:0,divisionMode:'divider',notes:''});
function seed(){const a=newOpening('Living room · left'),b=newOpening('Living room · right'),c=newOpening('Primary bedroom');c.width=48;c.height=72;c.quantity=2;return {schema:1,jobs:[{id:uid(),name:'Sample residence',customer:'Example customer',number:'DEMO-001',due:'',notes:'Example job for exploring the app. Replace these measurements before use.',sample:true,archived:false,updated:new Date().toISOString(),openings:[a,b,c]}],units:'in',outputUnits:'mm'};}
let state,storageError='',brandLogo=loadLogo(),logoBusy=false;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):seed();if(state.schema!==1||!Array.isArray(state.jobs))throw new Error('Invalid saved data');}catch{state=seed();storageError='Saved jobs could not be loaded. Export any current work before refreshing.';}
let activeJob=state.jobs.find(j=>!j.archived)?.id??null,activeOpening=null,view=activeJob?'editor':'jobs',tab='openings',archiveView=false,result=null,calcError='',calculating=false,requestNumber=0,invalidFields=new Map(),searchTerm='';
const notifiedLightGaps=new Map();
const remoteParams=new URLSearchParams(location.search),remoteKind=remoteParams.has('quote')?'quote':remoteParams.has('order')?'order':null;
let remoteContext=null,remoteSaving=false;

const money=value=>value==null?'Not priced':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(value/100);
const quoteEditing=()=>remoteContext?.kind==='quote'&&remoteContext.record.status!=='ordered';
const currentJob=()=>state.jobs.find(j=>j.id===activeJob),currentOpening=()=>currentJob()?.openings.find(o=>o.id===activeOpening)||currentJob()?.openings[0];
const panelCount=o=>o.tposts?o.tposts.sections.reduce((n,s)=>n+s.left+s.right,0):o.left+o.right;
const configuration=o=>o.tposts?o.tposts.sections.map(s=>'L'.repeat(s.left)+'R'.repeat(s.right)).join(' | T | '):'L'.repeat(o.left)+'R'.repeat(o.right);
const total=(j,key)=>j.openings.reduce((n,o)=>n+(key==='panels'?panelCount(o)*o.quantity:o.quantity),0);
const measure=(v,unit=state.units)=>unit==='mm'?String(Math.round(v*25.4*100)/100):String(Math.round(v*10000)/10000);
const cut=v=>state.outputUnits==='mm'?v.toFixed(2):(v/25.4).toFixed(4);
function save(touch=true){if(remoteContext){if(touch)remoteContext.dirty=true;const el=$('#save-state');if(el)el.textContent=remoteContext.dirty?'Unsaved opening changes':'Saved to shared workspace';refreshQuotePricing();return;}try{if(touch&&currentJob())currentJob().updated=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));storageError='';}catch{storageError='Browser storage is full or unavailable. Export a backup now to keep your work.';}const el=$('#save-state');if(el)el.innerHTML=icon(storageError?'info':'check')+h(storageError?'Not saved — export a backup':'Saved on this browser');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const btn=(label,action,ico,kind='')=>`<button class="btn ${kind}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
function sidebar(){return `<header class="app-header"><button class="wordmark" data-action="jobs" aria-label="Cut sheet home">${brandLogo?`<img class="brand-logo" src="${h(brandLogo.data)}" alt="Company logo">`:`${icon('panels')}Cut sheet`}</button><nav aria-label="Main navigation"><a class="nav-btn ${remoteContext?.kind==='quote'?'active':''}" href="/contacts.html">Contacts & quotes</a><a class="nav-btn ${remoteContext?.kind!=='quote'&&['editor','jobs'].includes(view)?'active':''}" href="/">Cut sheets</a><a class="nav-btn" href="/owner.html">Owner dashboard</a><a class="nav-btn" href="/shop.html">Shop floor</a>${remoteContext?'':`<button class="nav-btn ${view==='settings'?'active':''}" data-action="settings">Settings</button>`}</nav><span class="save-state" id="save-state">${icon(storageError?'info':'check')}${remoteContext?(remoteContext.dirty?'Unsaved opening changes':'Saved to shared workspace'):storageError?'Not saved — export a backup':'Saved on this browser'}</span></header>`;}
function render(){const j=currentJob();if(j&&!j.openings.some(o=>o.id===activeOpening))activeOpening=j.openings[0]?.id;$('#app').innerHTML=`${sidebar()}<main class="content">${storageError?`<div class="error-box">${h(storageError)}</div>`:''}${view==='editor'?editorPage():view==='settings'?settingsPage():jobsPage(view==='cutsheets')}</main>`;bind();if(view==='editor'&&tab==='openings'){validatePostFields();if($('.diagram-wrap'))$('.diagram-wrap').innerHTML=diagram(currentOpening());}if(view==='editor'&&tab!=='details'&&currentOpening())recalculate();}
function metrics(j){return `<div class="metrics">${[['panels','Openings',j.openings.length],['grid','Total units',total(j,'units')],['ruler','Total panels',total(j,'panels')],['clock','Job stage','Active']].map(([i,label,value])=>`<div class="metric"><div class="metric-icon">${icon(i)}</div><div><div class="metric-label">${label}</div><strong class="${typeof value==='string'?'small-value':''}">${value}</strong></div></div>`).join('')}</div>`;}
function editorPage(){if(remoteContext)return remoteEditorPage();const j=currentJob();if(!j){view='jobs';return jobsPage();}return `<div class="page-heading"><div><div class="eyebrow">${h(j.number)}${j.sample?' · EXAMPLE JOB':''}</div><h1>${h(j.name)}</h1><p class="subheading">${h(j.customer||'Customer not entered')}</p></div><div class="btn-row">${btn('Send to shop','send-shop','arrow')}${btn('Download PDF','pdf','download','primary')}</div></div><div class="tabs"><button class="tab ${tab==='openings'?'active':''}" data-tab="openings">Openings <span class="num">${j.openings.length}</span></button><button class="tab ${tab==='preview'?'active':''}" data-tab="preview">Cut sheet</button><button class="tab ${tab==='details'?'active':''}" data-tab="details">Job details</button></div>${tab==='details'?jobDetails():tab==='preview'?previewPage():openingWorkspace()}`;}
function miniature(){return `<svg class="mini-shutter" viewBox="0 0 44 36" aria-hidden="true"><rect x="2" y="1" width="40" height="34" rx="1" fill="none" stroke="currentColor"/><path d="M22 1v34 M5 7h14 M25 7h14 M5 13h14 M25 13h14 M5 19h14 M25 19h14 M5 25h14 M25 25h14 M5 31h14 M25 31h14" fill="none" stroke="currentColor"/></svg>`;}
function openingWorkspace(){const j=currentJob(),o=currentOpening();return `<div class="workspace"><aside class="opening-list" aria-label="Job openings">${j.openings.map((x,i)=>`<button class="opening-card ${x.id===o?.id?'active':''}" data-opening="${x.id}" aria-pressed="${x.id===o?.id}"><span class="opening-number">${String(i+1).padStart(2,'0')}</span><div><strong>${h(x.name)}</strong><div class="dims">${measure(x.width)} × ${measure(x.height)} ${state.units}</div><small>${panelCount(x)} panels · ${x.quantity} unit${x.quantity===1?'':'s'}</small>${quoteEditing()?`<span class="opening-line-price" data-price-opening="${x.id}">${h(money(openingPrice(x,remoteContext.record).lineTotal))}</span>`:''}</div></button>`).join('')}<button class="add-opening" data-action="add-opening">${icon('plus')}Add opening</button></aside>${o?openingEditor(o):`<div class="empty"><h2>Add your first opening</h2><p>Enter the measurements to get started.</p>${btn('Add opening','add-opening','plus','primary')}</div>`}</div>`;}
function inputField(key,label,value,{suffix='',type='text',wide=false,maxlength='80',help=''}={}){return `<div class="field ${wide?'wide':''}"><label for="${key}">${label}</label><div class="${suffix?'input-suffix':''}"><input id="${key}" data-field="${key}" value="${h(value)}" type="${type}" maxlength="${maxlength}" ${type==='number'?'min="1" max="100" step="1"':''} ${(['width','height','divider'].includes(key)||/^post-\d+$/.test(key))?'inputmode="decimal"':''}>${suffix?`<span>${suffix}</span>`:''}</div>${help?`<div class="field-help">${help}</div>`:''}<span class="field-error" id="error-${key}"></span></div>`;}
function selectField(key,label,value,options,wide=false){return `<div class="field ${wide?'wide':''}"><label for="${key}">${label}</label><select id="${key}" data-field="${key}">${Object.entries(options).map(([v,t])=>`<option value="${h(v)}" ${String(value)===v?'selected':''}>${h(t)}</option>`).join('')}</select></div>`;}
const LAYOUTS=STANDARD_LAYOUTS;
function layoutChoices(o){const choices=LAYOUTS[o.left+o.right]||[];return choices.some(([value])=>value===`${o.left}-${o.right}`)?choices:[...choices,[`${o.left}-${o.right}`,configuration(o),'Saved custom layout']];}
function panelConfiguration(o){if(o.tposts)return tpostConfiguration(o);return `<div class="construction-toggle" role="group" aria-label="Construction"><button type="button" data-construction="standard" aria-pressed="true">Standard</button><button type="button" data-construction="tpost" aria-pressed="false">T-post</button></div>`+standardPanelConfiguration(o);}
function standardPanelConfiguration(o){const n=o.left+o.right;return `<div class="config-heading"><h3>Panel configuration</h3><div class="segmented" role="group" aria-label="Number of panels">${[1,2,3,4].map(count=>`<button type="button" data-panel-count="${count}" aria-pressed="${n===count}" class="${n===count?'active':''}">${count} ${count===1?'panel':'panels'}</button>`).join('')}</div></div><div class="layout-options" role="group" aria-label="Panel arrangement">${layoutChoices(o).map(([value,code,label])=>`<button type="button" class="layout-option ${value===`${o.left}-${o.right}`?'selected':''}" data-layout="${value}" data-field="layout" value="${value}" aria-pressed="${value===`${o.left}-${o.right}`}" aria-label="${code} — ${label}">${drawingSVG({...o,width:Math.max(24,code.length*22),height:60,left:Number(value.split('-')[0]),right:Number(value.split('-')[1])},{thumbnail:true})}<strong>${code}</strong><small>${label}</small></button>`).join('')}</div><p class="field-help">Equal panel widths. Preview shows the folding direction from the front.</p>`;}
function tpostConfiguration(o){const t=o.tposts;return `<div class="construction-toggle" role="group" aria-label="Construction"><button type="button" data-construction="standard" aria-pressed="false">Standard</button><button type="button" data-construction="tpost" aria-pressed="true">T-post</button></div><div class="config-heading"><h3>T-post configuration</h3>${selectField('post-count','Number of posts',t.positions.length,{1:'1 post · 2 sections',2:'2 posts · 3 sections',3:'3 posts · 4 sections',4:'4 posts · 5 sections'})}</div><div class="tpost-presets" role="group" aria-label="Common T-post layouts">${TPOST_LAYOUTS.filter(p=>p.fractions.length===t.positions.length).map(p=>{const selected=t.sections.length===p.sections.length&&t.sections.every((section,i)=>section.left===p.sections[i].left&&section.right===p.sections[i].right);return `<button type="button" class="layout-option ${selected?'selected':''}" data-tpost-preset="${p.id}" aria-pressed="${selected}" aria-label="${p.description}">${drawingSVG({...o,width:88,height:60,tposts:{...t,positions:p.fractions.map(f=>f*88),sections:p.sections}},{thumbnail:true})}<strong>${p.label}</strong></button>`;}).join('')}</div><div class="tpost-positions">${t.positions.map((v,i)=>inputField('post-'+i,`Post ${i+1} centerline`,measurementInput(v,state.units),{suffix:state.units})).join('')}</div><p class="field-help">Measure each post centerline from the left edge of the entered opening, shutter, or outside-frame measurement.</p><div class="tpost-sections">${t.sections.map((section,i)=>selectField('section-'+i,`Section ${i+1} · ${i===0?'left':i===t.sections.length-1?'right':'middle'}`,`${section.left}-${section.right}`,{'1-0':'L','0-1':'R','2-0':'LL','1-1':'LR','0-2':'RR','2-1':'LLR','1-2':'LRR','2-2':'LLRR'})).join('')}</div><p class="field-help">Sections run left to right. Panels are equal within each section.</p><div class="post-construction">${selectField('post-construction','Post construction',t.construction,{'two-piece':'Two-piece · standard frame','one-piece':'One-piece · T-post'})}<button type="button" class="text-btn" data-space-posts>Space posts evenly</button></div>`;}
// Replacing all post positions also replaces their validation errors. Other invalid
// inputs must remain on screen so a configuration change cannot discard a draft.
function preparePostRedistribution(){
  if([...invalidFields.keys()].some(key=>!/^post-\d+$/.test(key))){toast('Correct the highlighted measurement first.');return false;}
  for(const key of [...invalidFields.keys()])if(/^post-\d+$/.test(key))invalidFields.delete(key);
  return true;
}
function bindPanelConfiguration(){document.querySelectorAll('[data-tpost-preset]').forEach(el=>el.onclick=()=>{if(!preparePostRedistribution())return;const o=currentOpening(),p=TPOST_LAYOUTS.find(p=>p.id===el.dataset.tpostPreset);o.tposts={construction:o.tposts?.construction||'two-piece',positions:p.fractions.map(f=>f*o.width),sections:structuredClone(p.sections)};save();render();});document.querySelectorAll('[data-construction]').forEach(el=>el.onclick=()=>{if(invalidFields.size)return toast('Correct the highlighted measurement first.');const o=currentOpening();if((el.dataset.construction==='tpost')===!!o.tposts)return;if(el.dataset.construction==='tpost')o.tposts={positions:[o.width/2],sections:[{left:1,right:0},{left:0,right:1}],construction:'two-piece'};else delete o.tposts;save();render();});document.querySelector('[data-space-posts]')?.addEventListener('click',()=>{if(!preparePostRedistribution())return;const o=currentOpening();o.tposts.positions=o.tposts.positions.map((_,i)=>o.width*(i+1)/(o.tposts.positions.length+1));save();render();});document.querySelectorAll('[data-layout]').forEach(el=>el.onclick=()=>{fieldChange(el);document.querySelectorAll('[data-layout]').forEach(b=>{const selected=b===el;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});});document.querySelectorAll('[data-panel-count]').forEach(el=>el.onclick=()=>{const o=currentOpening(),n=Number(el.dataset.panelCount);if(n===o.left+o.right)return;[o.left,o.right]=n===1?[1,0]:n===3?[2,1]:[n/2,n/2];save();$('#panel-configuration').innerHTML=panelConfiguration(o);bindPanelConfiguration();refreshOpeningSummary();recalculate();document.querySelector(`[data-panel-count="${n}"]`)?.focus();});}
function framePicker(o){const selected=frameStyle(o);return `<section class="frame-picker frame-picker-inline" aria-label="Frame style"><div class="frame-picker-heading"><h3>Frame style</h3><span>${h(selected.name)}</span></div><div class="frame-row">${FRAME_STYLES.filter(f=>f.available!==false).map(f=>`<button type="button" class="frame-choice ${selected.id===f.id?'selected':''}" data-frame-style="${f.id}" aria-pressed="${selected.id===f.id}" aria-label="${f.name}">${frameThumbnail(f.id)}<strong>${f.name}</strong></button>`).join('')}</div></section>${frameNotice(o)?`<p class="frame-notice">${h(frameNotice(o))}</p>`:''}`;}

const measurementNames={W:'Window opening size',S:'Shutter size',F:'Outside frame size'};
const measurementHelp=o=>o.sizeMethod==='W'?'Enter the window opening. The workbook applies fitting deductions for the selected frame.':o.sizeMethod==='S'?'Enter the ordered shutter size, after any fitting deductions. Matches the workbook’s SHUTTER FRM input.':'Enter the finished outside edges of the frame. Use an outside mount.';
const divisionHelp=o=>o.divisionMode==='split'?'Uses the workbook’s split-rod allowance. Leave the position blank to apply the allowance without a separate split.':'Leave the position blank for no divider rail.';
const lightGapHTML=()=>Number.isFinite(result?.gap)?`<p class="light-gap">Light gap <strong>${cut(result.gap)} ${state.outputUnits}</strong></p>`:'';
function openingEditor(o){return `<section class="editor-card"><div class="editor-header"><h2>Opening details</h2><div class="btn-row">${btn('Duplicate','duplicate-opening','copy','small ghost')}<button class="icon-btn" data-action="remove-opening" aria-label="Remove opening">${icon('trash')}</button></div></div><div class="essential-grid"><div><div class="fields">${inputField('name','Opening name',o.name,{wide:true})}</div><div class="measurement-heading"><span>Measurements</span><div class="input-unit-toggle" aria-label="Measurement units"><button data-input-unit="in" aria-pressed="${state.units==='in'}" class="${state.units==='in'?'active':''}">in</button><button data-input-unit="mm" aria-pressed="${state.units==='mm'}" class="${state.units==='mm'?'active':''}">mm</button></div></div><div class="measurement-basis">${selectField('sizeMethod','Measurement type',o.sizeMethod,{W:'Window opening size',S:'Shutter size',F:'Outside frame size'})}<p class="field-help" id="measurement-help">${measurementHelp(o)}</p></div><div class="measurement-fields">${inputField('width','Width',measurementInput(o.width,state.units),{suffix:state.units})}${inputField('height','Height',measurementInput(o.height,state.units),{suffix:state.units})}${inputField('quantity','Quantity',o.quantity,{type:'number'})}</div><p class="field-help">${state.units==='in'?'Inches: decimals such as 51.875 or 36.58, or fractions such as 36 5/8.':'Millimeters: whole numbers or decimals, such as 625 or 625.5.'}</p></div></div><section class="opening-preview" aria-label="Opening schematic"><div class="preview-heading"><span>Schematic preview</span><small>Front view · folds shown open</small></div><div class="diagram-wrap">${diagram(o)}</div></section>${framePicker(o)}<section class="panel-configuration" id="panel-configuration">${panelConfiguration(o)}</section><section class="more-options" aria-labelledby="opening-options-title"><h3 id="opening-options-title">Finish & other options</h3><div class="fields options-fields">${selectField('louver','Louver size',o.louver,{3:'3 inch',4:'4 inch'})}${selectField('mount','Mount',o.mount,{I:'Inside mount',O:'Outside mount'})}${selectField('color','Finish',o.color,COLORS)}${selectField('tilt','Tilt control',o.tilt,{Smart:'Smart View',Front:'Front tilt',Back:'Back tilt'})}${selectField('stile','Outside stile',o.stile,{Flat:'Flat',Reg:'Regular'})}${selectField('sides','Frame sides',o.sides,{'4W':'4 sides · window','3W':'3 sides · window','3D':'3 sides · door'})}${selectField('divisionMode','Rail / tilt-rod mode',o.divisionMode||'divider',{divider:'Divider rail',split:'Split tilt rod'})}${inputField('divider',o.divisionMode==='split'?'Split from bottom':'Divider from bottom',o.divider?measurementInput(o.divider,state.units):'',{suffix:state.units})}<p class="field-help wide" id="division-help">${divisionHelp(o)}</p><div class="field wide"><label for="notes">Shop notes</label><textarea id="notes" data-field="notes" maxlength="1200" placeholder="Optional instructions">${h(o.notes)}</textarea></div></div></section><div class="calculation-status" id="results">${loading()}</div></section>`;}

function diagram(o){if(invalidFields.size||o.tposts&&o.tposts.positions.some((v,i)=>v<=0||v>=o.width||i>0&&v<=o.tposts.positions[i-1]))return '<p class="preview-placeholder">Correct the highlighted measurements to see the full opening.</p>';return drawingSVG(o,{louverLayout:result?.status==='preview-only'?undefined:result?.louverLayout??null,widthLabel:`${measure(o.width)} ${state.units}`,heightLabel:`${measure(o.height)} ${state.units}`})+(result?.louverLayout?`<p class="louver-count">${h(louverSummary(result))}</p>`:'');}
const loading=()=>'<div class="loading-text">Calculating from workbook rules…</div><div class="skeleton"></div>';
function partTable(parts){return `<div class="table-scroll"><table><thead><tr><th>PART / PROFILE</th><th class="number">QTY</th><th class="number">CUT LENGTH (${state.outputUnits})</th></tr></thead><tbody>${parts.map((p,i)=>`<tr><td>${h(p.name)}${p.section?` <span class="part-section">· section ${p.section}</span>`:''}<small>${h(p.profile)}</small></td><td class="number">${p.quantity}</td><td class="number" style="font-weight:650;color:#151515">${cut(p.length)} <span style="font-size:9px;font-weight:400;color:#777777">${state.outputUnits}</span></td></tr>`).join('')}</tbody></table></div>`;}

function resultsHTML(){if(calculating)return loading();if(calcError)return `<div class="error-box">${icon('info')} ${h(calcError)}</div>`;if(!result)return '';return `<div class="results-heading"><div><h3>Calculated cutting list</h3><p>${result.parts.length} part lines · quantities include all identical units</p></div><span class="badge">${icon('check')} Workbook rules</span></div>${result.warnings.length?`<div class="error-box" role="alert">${result.warnings.map(h).join('<br>')}</div>`:''}${partTable(result.parts)}${result.reviewNotes?.length?`<div class="validation-note">${icon('info')}${result.reviewNotes.map(h).join(' ')}</div>`:''}`;}
function calculationStatus(){if(calculating)return loading();if(calcError)return `<div class="error-box" role="alert">${h(calcError)}</div>`;if(!result)return '';if(result.status==='preview-only')return `<div class="error-box" role="alert">${result.warnings.map(h).join('<br>')}</div>`;if(quoteEditing())return `${result.warnings.length?`<div class="error-box" role="alert">${result.warnings.map(h).join('<br>')}</div>`:'<div class="status-line">Opening specifications calculated</div>'}${lightGapHTML()}`;return `${result.warnings.length?`<div class="error-box" role="alert">${result.warnings.map(h).join('<br>')}</div>`:''}<div class="status-line"><span>${icon('check')}${result.parts.length} cut lines calculated</span><button class="text-btn" id="review-cut-sheet">Review cut sheet →</button></div>${lightGapHTML()}${result.reviewNotes?.length?`<details class="review-note"><summary>Fabrication notes to verify</summary><p>${result.reviewNotes.map(h).join(' ')}</p></details>`:''}`;}
async function recalculate({notifyGap=true}={}){const o=currentOpening();const serial=++requestNumber;result=null;calcError='';calculating=true;const target=$('#results')||$('#preview-content');if(!target)return;if(invalidFields.size){calculating=false;calcError='Correct the highlighted measurements to calculate this opening.';target.innerHTML=calculationStatus();return;}target.innerHTML=loading();if($('.diagram-wrap'))$('.diagram-wrap').innerHTML=diagram(o);try{const response=await fetch('/api/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});const data=await response.json();if(serial!==requestNumber)return;if(!response.ok)throw new Error(data.error);result=data;}catch(e){if(serial!==requestNumber)return;calcError=e.message==='Failed to fetch'?'The local app server is unavailable. Start the app server and retry.':e.message;}if(serial!==requestNumber)return;calculating=false;if($('.diagram-wrap'))$('.diagram-wrap').innerHTML=diagram(o);if(tab==='preview'&&$('#preview-content')){$('#preview-content').innerHTML=previewContent();}else if($('#results'))$('#results').innerHTML=calculationStatus();checkLightGap(o,notifyGap);}
function checkLightGap(o,notify){
  if(!result)return;
  const key=`${currentJob()?.id}:${o.id}`,warning=result.lightGapWarning;
  if(!warning){notifiedLightGaps.delete(key);return;}
  if(!notify||notifiedLightGaps.get(key)===warning||$('#modal').open)return;
  notifiedLightGaps.set(key,warning);
  modal('Light gap needs attention',`<p><strong>${h(o.name)}</strong></p><p>${h(warning)}</p><p>Current light gap: <strong>${cut(result.gap)} ${state.outputUnits}</strong></p>`,btn('Got it','close',null,'primary'));
}
function previewPage(){const j=currentJob();if(!j.openings.length)return `<div class="empty">${icon('file')}<h2>Add an opening to preview a cut sheet.</h2>${btn('Add opening','add-opening','plus','primary')}</div>`;return `<div class="preview-toolbar"><select id="preview-opening" aria-label="Opening to preview" style="max-width:280px">${j.openings.map(o=>`<option value="${o.id}" ${o.id===activeOpening?'selected':''}>${h(o.name)}</option>`).join('')}</select></div><div id="preview-content">${loading()}</div>`;}
function previewWarning(message){
  if(message.includes('WRONG MOUNT OPTION OR FRAME'))return message.replace(/WRONG MOUNT OPTION OR FRAME(?:\s*!)*/g, 'This frame and mount combination is not supported. Check Frame style and Mount in Finish & other options, then try again.');
  return message;
}
function previewContent(){
  if(!result&&!calcError)return loading();
  const j=currentJob(),o=currentOpening(),warnings=calcError?[calcError]:(result.warnings||[]),hasCuts=result&&result.status!=='preview-only';
  const facts=cutSheetFacts(o,result,{measurement:measure,length:cut,inputUnits:state.units,units:state.outputUnits});
  const machining=hasCuts?[['Hinges from stile end',result.hinges.map(cut).join(' · ')],...result.machining.map(m=>[machiningLabel(m.label),cut(m.value)])]:[];
  const notes=cutSheetNotes(result);
  return `<article class="paper"><header class="paper-header paper-header-compact"><div><small>CUT SHEET</small><p>${h(j.number)}${j.customer?` · ${h(j.customer)}`:''}</p></div>${remoteContext?.kind==='order'||remoteContext?.record.status==='ordered'?'':'<button type="button" class="text-btn" data-edit-opening>Edit opening</button>'}</header><h2 class="paper-opening-title">${h(o.name)}</h2><section class="paper-opening"><dl class="spec-grid">${facts.map(([label,value])=>`<div><dt>${h(label)}</dt><dd>${h(value)}</dd></div>`).join('')}</dl><figure class="paper-shutter-preview" aria-label="Shutter preview">${diagram(o)}</figure></section>${o.tposts?`<p class="paper-posts">${o.tposts.construction==='two-piece'?'Two-piece':'One-piece'} posts · Centerlines from left (${state.outputUnits}): ${o.tposts.positions.map(v=>cut(v*25.4)).join(' · ')}</p>`:''}${warnings.length?`<div class="paper-issue" role="alert"><div>${warnings.map(w=>`<p>${h(previewWarning(w))}</p>`).join('')}</div>${remoteContext?.kind==='order'||remoteContext?.record.status==='ordered'?'':'<button type="button" class="text-btn" data-edit-opening>Review options</button>'}</div>`:''}${hasCuts?`${partTable(result.parts)}<section class="paper-machining"><h3>Machining <span>(${state.outputUnits})</span></h3><dl class="spec-grid">${machining.map(([label,value])=>`<div><dt>${h(label)}</dt><dd>${h(value)}</dd></div>`).join('')}</dl></section>${notes.length?`<div class="paper-notes">${notes.map(n=>`<p>${h(n)}</p>`).join('')}</div>`:''}${o.notes?`<p class="paper-notes"><b>Shop notes:</b> ${h(o.notes)}</p>`:''}`:''}<div class="paper-footer">Cut lengths in ${state.outputUnits}</div></article>`;
}
function jobDetails(){const j=currentJob();return `<section class="details-card"><h2>Job details</h2><p class="subheading" style="margin:7px 0 25px">Keep the order details together with every opening.</p><div class="fields">${inputField('job-name','Job name',j.name,{wide:true,maxlength:'100'})}${inputField('job-customer','Customer',j.customer,{maxlength:'120'})}${inputField('job-number','Job number',j.number,{maxlength:'120'})}${inputField('job-due','Target date',j.due,{type:'date'})}<div class="field wide"><label for="job-notes">Job notes</label><textarea id="job-notes" data-job-field="notes" maxlength="1200">${h(j.notes)}</textarea></div></div><div class="btn-row">${btn(j.archived?'Restore job':'Archive job','archive-job','archive','ghost')}${btn('Back to openings','back-openings','arrow','primary')}</div></section>`;}
function jobsPage(cutsheets=false){const jobs=state.jobs.filter(j=>!!j.archived===archiveView);return `<div class="page-heading"><div><div class="eyebrow">YOUR JOBS</div><h1>${cutsheets?'Cut sheets':archiveView?'Archived jobs':'Jobs'}</h1><p class="subheading">${cutsheets?'Clean, organized cutting lists for every opening.':'Measurements and cut sheets, together.'}</p></div>${btn('New job','new-job','plus','primary')}</div><div class="jobs-toolbar"><div class="search">${icon('search')}<input id="job-search" placeholder="Search jobs, customers, or job numbers…" aria-label="Search jobs" value="${h(searchTerm)}"></div><div class="btn-row">${btn(archiveView?'Active jobs':'View archive','toggle-archive','archive','small')}${btn('Import backup','import','upload','small')}</div></div><div class="job-grid" id="job-grid">${jobCards(jobs,cutsheets)}</div>`;}
function jobCards(jobs,cutsheets){const found=jobs.filter(j=>`${j.name} ${j.customer} ${j.number}`.toLowerCase().includes(searchTerm.toLowerCase()));return found.length?found.map(j=>`<button class="job-card" data-job="${j.id}" ${cutsheets?'data-preview="true"':''}>${icon(cutsheets?'file':'jobs')}<div class="eyebrow">${h(j.number)} ${j.sample?' / EXAMPLE':''}</div><h2>${h(j.name)}</h2><p>${h(j.customer||'Customer not entered')}</p><footer><span>${j.openings.length} openings · ${total(j,'units')} units</span><span class="badge ${j.archived?'ghost':'amber'}">${j.archived?'Archived':'Active'}</span></footer></button>`).join(''):`<div class="empty" style="grid-column:1/-1">${icon('jobs')}<h2>${searchTerm?'No matching jobs.':archiveView?'No archived jobs.':'Your next job belongs here.'}</h2><p>${searchTerm?'Try a different customer or job number.':'Create a job, add openings, and generate your cutting lists.'}</p></div>`;}
function brandingSettings(){return `<section class="settings-card branding-settings"><h2>Company logo</h2><p>Show your logo in the top-left corner of the app. Saved in this browser.</p><div class="logo-preview">${brandLogo?`<img src="${h(brandLogo.data)}" alt="Current company logo">`:`<span>${icon('panels')}<b>Cut sheet</b></span>`}</div>${brandLogo?`<p class="logo-filename">${h(brandLogo.name)}</p>`:''}<div class="btn-row"><button type="button" class="btn" id="upload-logo">${icon('upload')}${brandLogo?'Replace logo':'Upload logo'}</button>${brandLogo?'<button type="button" class="text-btn" id="remove-logo">Remove logo</button>':''}<input type="file" id="logo-file" accept="image/png,image/jpeg,image/webp" hidden></div><p class="logo-help">PNG, JPG, or WebP · Up to 5 MB. A transparent PNG works best.</p><div id="logo-error" class="field-error" role="alert"></div></section>`;}
function bindBranding(){
  $('#upload-logo')?.addEventListener('click',()=>$('#logo-file').click());
  $('#logo-file')?.addEventListener('change',async e=>{
    const file=e.target.files[0];if(!file||logoBusy)return;
    logoBusy=true;const button=$('#upload-logo');button.disabled=true;button.textContent='Saving logo…';$('#logo-error').textContent='';
    try{const logo=await readLogoFile(file);try{saveLogo(logo);}catch{throw new Error('The logo could not be saved. Browser storage may be full. Try a smaller image.');}brandLogo=logo;render();toast('Logo updated.');}
    catch(error){if($('#logo-error'))$('#logo-error').textContent=error.message;else toast(error.message);}
    finally{logoBusy=false;if($('#upload-logo')){$('#upload-logo').disabled=false;$('#upload-logo').innerHTML=icon('upload')+(brandLogo?'Replace logo':'Upload logo');}if($('#logo-file'))$('#logo-file').value='';}
  });
  $('#remove-logo')?.addEventListener('click',()=>{
    if(logoBusy)return;
    try{saveLogo(null);brandLogo=null;render();toast('Logo removed.');}catch{$('#logo-error').textContent='The logo could not be removed. Please try again.';}
  });
}
function settingsPage(){return `<div class="page-heading"><div><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><p class="subheading">Logo, units, backups, and calculation details.</p></div></div><div class="settings-layout">${brandingSettings()}<section class="settings-card"><h2>Measurements & output</h2><p>Input units can change without altering the physical dimensions. PDF and cutting-list units are controlled separately.</p><div class="fields">${selectField('settings-input','Input measurements',state.units,{in:'Inches (decimals or fractions)',mm:'Millimeters'})}${selectField('settings-output','Cut sheet dimensions',state.outputUnits,{mm:'Millimeters · 2 decimals',in:'Decimal inches · 4 decimals'})}</div><div class="row" style="margin-top:16px"><span>Paper size</span><b>US Letter · portrait</b></div><div class="row"><span>Opening organization</span><b>Each opening starts on a new page</b></div><div class="row"><span>Saw-kerf allowance</span><b>None added</b></div></section><section class="settings-card"><h2>Calculation source</h2><p>Extracted from your FRENCH CUT NEW PROGRAM workbook. The app evaluates the original formulas for the supported configuration.</p><div class="row"><span>Workbook version</span><b>20170211FCNew</b></div><div class="row"><span>Product family</span><b>Shutter Smart</b></div><div class="row"><span>Configuration</span><b>Standard and T-post</b></div><div class="row"><span>Production validation</span><b style="color:var(--amber)">Pending reference cut sheets</b></div><p style="margin:17px 0 0"><a href="https://docs.google.com/spreadsheets/d/1FGIwG2DLI-5FSbQ9KTH9_tn0t5dYAbkG/edit" target="_blank" rel="noopener">Open source workbook ↗</a></p></section><section class="settings-card"><h2>Saved jobs</h2><p>Jobs are stored in this browser on this computer. Export backups regularly, or import one to move jobs to another browser. Importing merges jobs by ID.</p><div class="btn-row">${btn('Export backup','backup','download')}${btn('Import backup','import','upload')}</div></section><section class="settings-card"><h2>What this version supports</h2><ul><li>Standard: 1, 2, 3, or 4 equal panels</li><li>T-post: 1–4 posts with a panel arrangement for each section</li><li>3 inch and 4 inch louvers</li><li>Standard, designer, Z, and trim frames</li><li>Inside and outside mounts</li><li>One optional divider rail or tilt-rod split</li><li>Opening PDFs and combined cutting lists</li></ul><p>French cuts, double-hung, wood, and specialty hardware are not enabled in this version.</p></section></div>`;}

function bind(){bindPanelConfiguration();bindBranding();$('#preview-content')?.addEventListener('click',e=>{if(e.target.closest('[data-edit-opening]')){const needsMountReview=result?.warnings.some(w=>w.includes('WRONG MOUNT OPTION OR FRAME'));tab='openings';render();if(needsMountReview){$('#mount').focus();}else $('#name')?.focus();}});document.querySelectorAll('[data-frame-style]').forEach(el=>el.addEventListener('click',()=>{if(invalidFields.size)return toast('Correct the highlighted measurement first.');const o=currentOpening(),style=FRAME_STYLES.find(f=>f.id===el.dataset.frameStyle);if(style.profile){o.frame=style.profile;delete o.frameStyle;}else{o.frameStyle=style.id;}save();render();}));$('#results')?.addEventListener('click',e=>{if(e.target.closest('#review-cut-sheet')){if(invalidFields.size)return toast('Correct the highlighted measurement first.');tab='preview';render();}});document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action)));document.querySelectorAll('[data-job]').forEach(el=>el.addEventListener('click',()=>{if(invalidFields.size)return toast('Correct the highlighted measurement first.');activeJob=el.dataset.job;activeOpening=null;invalidFields.clear();view='editor';tab=el.dataset.preview?'preview':'openings';render();}));document.querySelectorAll('[data-opening]').forEach(el=>el.addEventListener('click',()=>{if(invalidFields.size){toast('Correct the highlighted measurement before switching openings.');return;}activeOpening=el.dataset.opening;render();}));document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>{if(invalidFields.size){toast('Correct the highlighted measurement first.');return;}tab=el.dataset.tab;render();}));document.querySelectorAll('[data-input-unit]').forEach(el=>el.addEventListener('click',()=>{if(invalidFields.size)return toast('Correct the highlighted measurement first.');state.units=el.dataset.inputUnit;save();render();}));document.querySelectorAll('[data-field]').forEach(el=>{el.addEventListener('change',()=>fieldChange(el));if(el.tagName!=='SELECT')el.addEventListener('input',()=>fieldChange(el,false));});$('#job-notes')?.addEventListener('change',e=>{currentJob().notes=e.target.value;save();});$('#preview-opening')?.addEventListener('change',e=>{activeOpening=e.target.value;recalculate();});$('#job-search')?.addEventListener('input',e=>{searchTerm=e.target.value;$('#job-grid').innerHTML=jobCards(state.jobs.filter(j=>!!j.archived===archiveView),view==='cutsheets');document.querySelectorAll('[data-job]').forEach(el=>el.addEventListener('click',()=>{activeJob=el.dataset.job;activeOpening=null;view='editor';tab=el.dataset.preview?'preview':'openings';render();}));});}
function fieldChange(el,notifyGap=true){const key=el.dataset.field;if(key==='post-count'){const o=currentOpening();if(!preparePostRedistribution()){el.value=String(o.tposts.positions.length);return;}const n=Number(el.value);o.tposts.positions=Array.from({length:n},(_,i)=>o.width*(i+1)/(n+1));o.tposts.sections=Array.from({length:n+1},(_,i)=>o.tposts.sections[i]||{left:1,right:1});save();render();return;}if(key.startsWith('settings-')){state[key==='settings-input'?'units':'outputUnits']=el.value;save();return;}if(key.startsWith('job-')){const k=key.slice(4);if(['name','number'].includes(k)&&!el.value.trim()){toast('Job name and number cannot be blank.');el.setAttribute('aria-invalid','true');return;}el.removeAttribute('aria-invalid');currentJob()[k]=el.value.trim();save();if(k==='name')$('.page-heading h1').textContent=currentJob().name;if(k==='customer')$('.page-heading .subheading').textContent=currentJob().customer||'Customer not entered';return;}const o=currentOpening();try{let value=el.value;if(['width','height','divider'].includes(key)||/^post-\d+$/.test(key)){value=key==='divider'&&!value.trim()?0:parseMeasurement(value);if(state.units==='mm')value/=25.4;if(!Number.isFinite(value))throw new Error('Enter a finite measurement.');if(key!=='divider'&&value<=0)throw new Error('Measurement must be greater than zero.');if(key==='width'&&!o.tposts&&value>106||key==='height'&&value>114)throw new Error(`The workbook limit is ${key==='width'?106:114} inches.`);}else if(['quantity','louver'].includes(key)){value=Number(value);if(!Number.isInteger(value)||value<1||value>100)throw new Error('Enter a whole number between 1 and 100.');}else if(key==='name'){value=value.trim();if(!value)throw new Error('Give this opening a name.');}if(key==='layout'){[o.left,o.right]=value.split('-').map(Number);}else if(/^post-\d+$/.test(key)){o.tposts.positions[Number(key.slice(5))]=value;}else if(/^section-\d+$/.test(key)){const [left,right]=value.split('-').map(Number);o.tposts.sections[Number(key.slice(8))]={left,right};}else if(key==='post-construction'){o.tposts.construction=value;}else{o[key]=value;}invalidFields.delete(key);el.removeAttribute('aria-invalid');const err=$('#error-'+key);if(err)err.textContent='';validatePostFields();save();refreshOpeningSummary();recalculate({notifyGap});}catch(e){delete el.dataset.geometryError;invalidFields.set(key,e.message);el.setAttribute('aria-invalid','true');const err=$('#error-'+key);if(err)err.textContent=e.message;refreshOpeningSummary();recalculate();}}
function validatePostFields(){
  const o=currentOpening();if(!o?.tposts)return;
  for(let i=0;i<o.tposts.positions.length;i++){const key='post-'+i,el=$('#'+key);if(el?.dataset.geometryError){invalidFields.delete(key);delete el.dataset.geometryError;el.removeAttribute('aria-invalid');$('#error-'+key).textContent='';}}
  o.tposts.positions.forEach((value,i)=>{const key='post-'+i,el=$('#'+key);if(!el||invalidFields.has(key))return;const previous=i?o.tposts.positions[i-1]:0;let message='';if(value<=0||value>=o.width)message=`Post ${i+1} must be inside the ${measure(o.width)} ${state.units} opening.`;else if(value<=previous)message=`Post ${i+1} must be farther right than post ${i} (${measure(previous)} ${state.units}).`;if(message){invalidFields.set(key,message);el.dataset.geometryError='true';el.setAttribute('aria-invalid','true');$('#error-'+key).textContent=message;}});
}
function refreshOpeningSummary(){
  const o=currentOpening(),card=document.querySelector(`[data-opening="${o.id}"]`);
  if($('#measurement-help'))$('#measurement-help').textContent=measurementHelp(o);
  if($('#division-help'))$('#division-help').textContent=divisionHelp(o);
  const dividerLabel=document.querySelector('label[for="divider"]');if(dividerLabel)dividerLabel.textContent=o.divisionMode==='split'?'Split from bottom':'Divider from bottom';
  if(card){card.querySelector('strong').textContent=o.name;card.querySelector('.dims').innerHTML=`${measure(o.width)} <span style="color:#777777;font-size:12px">×</span> ${measure(o.height)} <span style="font-size:10px;color:#777777">${state.units}</span>`;card.querySelector('small').textContent=`${panelCount(o)} panels · ${o.quantity} unit${o.quantity===1?'':'s'}`;}
  refreshQuotePricing();
  if($('.metrics'))$('.metrics').outerHTML=metrics(currentJob());
  if($('.diagram-wrap'))$('.diagram-wrap').innerHTML=diagram(o);
  document.querySelectorAll('[data-tpost-preset]').forEach(el=>{const p=TPOST_LAYOUTS.find(p=>p.id===el.dataset.tpostPreset),selected=!!o.tposts&&o.tposts.sections.length===p.sections.length&&o.tposts.sections.every((section,i)=>section.left===p.sections[i].left&&section.right===p.sections[i].right);el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});
  const stats=document.querySelectorAll('.diagram-stats strong');if(stats.length){stats[0].textContent=`${o.left} left / ${o.right} right`;stats[1].textContent=`${o.louver} inch`;}
  const summary=document.querySelectorAll('.summary-box .row b');if(summary.length){summary[1].textContent=COLORS[o.color];summary[2].textContent=FRAMES[o.frame];summary[3].textContent=panelCount(o)*o.quantity;}
}
function modal(title,body,footer){const d=$('#modal');d.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="icon-btn" id="modal-close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footer}</div>`;$('#modal-close').onclick=()=>d.close();d.showModal();d.querySelectorAll('[data-action="close"]').forEach(x=>x.onclick=()=>d.close());}
function openNewJob(){modal('Start a new job',`<p>Give the job a name. You can add openings right after.</p><form id="new-job-form"><div class="fields"><div class="field wide"><label for="new-name">Job name</label><input id="new-name" name="name" placeholder="e.g. Hawthorne residence" maxlength="100" required autofocus></div><div class="field wide"><label for="new-customer">Customer</label><input id="new-customer" name="customer" maxlength="120" placeholder="Customer or company"></div><div class="field wide"><label for="new-number">Job number</label><input id="new-number" name="number" maxlength="120" value="JOB-${String(state.jobs.filter(j=>!j.sample).length+1).padStart(3,'0')}" required></div></div><p class="field-error" id="modal-error" style="margin:12px 0 0"></p></form>`,`${btn('Cancel','close',null)}<button class="btn primary" type="submit" form="new-job-form">Create job ${icon('arrow')}</button>`);$('#new-job-form').onsubmit=e=>{e.preventDefault();const name=$('#new-name').value.trim(),number=$('#new-number').value.trim();if(!name||!number)return $('#modal-error').textContent='Enter a job name and number.';const j={id:uid(),name,number,customer:$('#new-customer').value.trim(),due:'',notes:'',sample:false,archived:false,updated:new Date().toISOString(),openings:[]};state.jobs.unshift(j);activeJob=j.id;activeOpening=null;view='editor';tab='openings';invalidFields.clear();save();$('#modal').close();render();toast('Job created. Add your first opening.');};}
async function sendToShop(){
  if(invalidFields.size)return toast('Correct the highlighted measurement before sending to the shop.');
  const job=currentJob();if(!job?.openings.length)return toast('Add an opening first.');
  try{
    const session=await shopRequest('session');
    if(!session.configured){toast('Connect shared shop storage on the hosted site first.');return;}
    if(session.role!=='owner'){location.href='/owner.html';return;}
  }catch(error){return toast(error.message);}
  modal('Send job to shop',`<p>The shop receives a fixed copy of every calculated cut sheet in <strong>${h(job.name)}</strong>. Later edits here will not change a released job.</p><form id="release-form"><div class="fields"><div class="field"><label for="release-time">Estimated cutting time (minutes)</label><input id="release-time" type="number" min="0" max="60000" step="1" placeholder="e.g. 90"></div><div class="field"><label for="release-due">Target date</label><input id="release-due" type="date" value="${h(job.due||'')}"></div></div><p class="field-help">The timer tracks active cutting time and excludes pauses. An estimate lets the dashboard flag jobs running over.</p></form><p class="field-error" id="release-error" role="alert"></p>`,`${btn('Cancel','close')}<button class="btn primary" type="submit" form="release-form" id="release-save">Send to shop</button>`);
  $('#release-form').onsubmit=async event=>{
    event.preventDefault();const button=$('#release-save');button.disabled=true;button.textContent='Sending…';
    try{if(remoteContext?.kind==='order')await shopRequest('order-release',{id:remoteContext.record.id,version:remoteContext.record.version,targetMinutes:Number($('#release-time').value),due:$('#release-due').value});else await shopRequest('publish',{job:structuredClone(job),targetMinutes:Number($('#release-time').value),due:$('#release-due').value});$('#modal').close();toast('Job sent to shop. Track it in the owner dashboard.');}
    catch(error){$('#release-error').textContent=previewWarning(error.message);button.disabled=false;button.textContent='Send to shop';}
  };
}
function openPDF(){if(invalidFields.size)return toast('Correct the highlighted measurement before generating a PDF.');const j=currentJob();if(!j||!j.openings.length)return toast('Add at least one opening first.');modal('Generate cut sheets',`<p>A clean US Letter PDF, ready to save or print. Dimensions are labeled on every page.</p><label class="option-card"><input type="radio" name="pdf-mode" value="all" checked><span><strong>All openings</strong><small>Each opening starts on a new page · ${j.openings.length} openings</small></span></label><label class="option-card"><input type="radio" name="pdf-mode" value="current"><span><strong>Selected opening</strong><small>${h(currentOpening()?.name)}</small></span></label><label class="option-card"><input type="radio" name="pdf-mode" value="combined"><span><strong>Combined cutting list</strong><small>Matching parts grouped by exact size, finish, and profile</small></span></label><div class="field" style="margin-top:19px"><label for="pdf-units">Cut length units</label><select id="pdf-units"><option value="mm" ${state.outputUnits==='mm'?'selected':''}>Millimeters · 2 decimals</option><option value="in" ${state.outputUnits==='in'?'selected':''}>Decimal inches · 4 decimals</option></select></div><p class="field-error" id="pdf-error" role="alert" style="margin:12px 0 0"></p>`,`${btn('Cancel','close',null)}<button class="btn primary" id="download-pdf">${icon('download')}Download PDF</button>`);$('#download-pdf').onclick=async()=>{const button=$('#download-pdf'),mode=$('input[name="pdf-mode"]:checked').value;button.disabled=true;button.textContent='Generating PDF…';$('#pdf-error').textContent='';try{const snapshot=structuredClone(j);if(mode==='current')snapshot.openings=[structuredClone(currentOpening())];const response=await fetch('/api/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job:snapshot,combined:mode==='combined',units:$('#pdf-units').value})});if(!response.ok){const data=await response.json();throw new Error(data.error);}download(await response.blob(),`${j.number.replace(/[^\w-]/g,'-')}-${mode==='combined'?'combined-list':mode==='current'?'opening':'cut-sheets'}.pdf`);$('#modal').close();toast('PDF downloaded. Open it to print.');}catch(e){$('#pdf-error').textContent=previewWarning(e.message);button.disabled=false;button.innerHTML=icon('download')+'Download PDF';}};}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function backup(){download(new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),`cut-sheet-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Backup exported. Keep it somewhere safe.');}
async function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>5e6)throw new Error('Backup must be smaller than 5 MB.');const data=JSON.parse(await file.text());if(data.schema!==1||!Array.isArray(data.jobs)||data.jobs.length>500)throw new Error('This is not a compatible job backup.');const seen=new Set();for(const j of data.jobs){if(typeof j.id!=='string'||!/^[-a-zA-Z0-9]{1,64}$/.test(j.id)||seen.has(j.id)||typeof j.name!=='string'||j.name.length>100||typeof j.number!=='string'||j.number.length>120||typeof j.customer!=='string'||j.customer.length>120||!Array.isArray(j.openings)||j.openings.length>100||typeof j.updated!=='string')throw new Error('Backup contains an invalid job.');seen.add(j.id);const ids=new Set();for(const o of j.openings){if(typeof o.id!=='string'||!/^[-a-zA-Z0-9]{1,64}$/.test(o.id)||ids.has(o.id)||typeof o.name!=='string'||o.name.length>80)throw new Error('Backup contains an invalid opening.');ids.add(o.id);const r=await fetch('/api/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});if(!r.ok)throw new Error(`Cannot import ${o.name}: ${(await r.json()).error}`);}}
    // Newer local jobs win. Restore does not silently replace subsequent work with an old backup.
    let count=0;for(const j of data.jobs){const i=state.jobs.findIndex(x=>x.id===j.id);if(i<0){state.jobs.push(j);count++;}else if(j.updated>state.jobs[i].updated){state.jobs[i]=j;count++;}}
    save(false);view='jobs';render();toast(`${count} jobs imported or updated. Existing newer jobs kept.`);
  }catch(e){toast(e.message);}};input.click();}
function action(name){if(remoteContext&&['remote-save','remote-back'].includes(name))return saveRemote(name==='remote-back');if(remoteContext&&['jobs','cutsheets','settings','new-job','archive-job','import','backup'].includes(name))return toast('Save your opening changes and return to the quote or order first.');if(['jobs','cutsheets','settings'].includes(name)){if(invalidFields.size)return toast('Correct the highlighted measurement before leaving this opening.');view=name;render();return;}
  if(name==='send-shop')return sendToShop();if(name==='new-job')return openNewJob();if(name==='pdf')return openPDF();if(name==='backup')return backup();if(name==='import')return importBackup();
  if(name==='toggle-archive'){archiveView=!archiveView;render();return;}
  if(name==='details'||name==='back-openings'){if(invalidFields.size)return toast('Correct the highlighted measurement first.');tab=name==='details'?'details':'openings';render();return;}
  if(name==='add-opening'){if(invalidFields.size)return toast('Correct the highlighted measurement first.');const j=currentJob();if(j.archived)return toast('Restore the job before adding openings.');if(j.openings.length>=100)return toast('A job can hold up to 100 openings.');const o=newOpening(`Opening ${j.openings.length+1}`);j.openings.push(o);activeOpening=o.id;tab='openings';save();render();$('#name')?.focus();$('#name')?.select();return;}
  if(name==='duplicate-opening'){if(invalidFields.size)return toast('Correct the highlighted measurement first.');const j=currentJob();if(j.openings.length>=100)return toast('A job can hold up to 100 openings.');const o=structuredClone(currentOpening());o.id=uid();o.name=(o.name+' (copy)').slice(0,80);j.openings.push(o);activeOpening=o.id;save();render();toast('Opening duplicated. Adjust the name and measurements.');return;}
  if(name==='remove-opening'){const o=currentOpening();modal('Remove this opening?',`<p>Remove <b>${h(o.name)}</b> from this job? Other openings stay in place.</p>`,`${btn('Keep opening','close',null)}<button class="btn danger" id="confirm-remove">Remove opening</button>`);$('#confirm-remove').onclick=()=>{currentJob().openings=currentJob().openings.filter(x=>x.id!==o.id);invalidFields.clear();activeOpening=null;save();$('#modal').close();render();toast('Opening removed.');};return;}
  if(name==='archive-job'){const j=currentJob();j.archived=!j.archived;save();view='jobs';archiveView=false;render();toast(j.archived?'Job archived. Find it in View archive.':'Job restored.');}
}
function quotePricingHTML(){
  if(!quoteEditing())return '';
  const q={...remoteContext.record,openings:currentJob().openings},t=quotePricing(q);
  if(!q.openings.length)return '';
  if(invalidFields.size)return '<p class="field-error">Correct the highlighted measurements to update quote pricing.</p>';
  return `<div class="sales-section-heading"><h2>Quote line items</h2><span class="subheading">${q.pricing?.rateCents==null?'No square-foot rate saved':money(q.pricing.rateCents)+' / sq ft'} · ${q.openings.length} opening${q.openings.length===1?'':'s'}</span></div><div class="sales-table"><table><thead><tr><th>OPENING</th><th>SIZE (IN)</th><th>QTY</th><th class="number">EACH</th><th class="number">LINE TOTAL</th></tr></thead><tbody>${q.openings.map((o,i)=>`<tr><td>${h(o.name)}</td><td>${o.width} × ${o.height}</td><td>${o.quantity}</td><td class="number">${money(t.lines[i].unitPrice)}</td><td class="number"><strong>${money(t.lines[i].lineTotal)}</strong></td></tr>`).join('')}</tbody></table></div><div class="builder-totals">${[['Products',t.subtotal],['Discount',-t.discount],['Installation',t.installation],['Tax',t.tax]].filter(([label,value])=>label==='Products'||value).map(([label,value])=>`<div><span>${label}</span><strong>${money(value)}</strong></div>`).join('')}<div class="builder-total"><span>${t.unpriced?'Priced items subtotal':'Quote total'}</span><strong>${money(t.total)}</strong></div></div>${t.unpriced?'<p class="field-help">Set the ShutterSmart rate in Pricing, then use current pricing on the proposal review to price these lines.</p>':''}${t.discount>t.subtotal?'<p class="field-error">The saved discount exceeds the new subtotal. Adjust it on the proposal before changing these openings.</p>':''}`;
}
function refreshQuotePricing(){
  if(!quoteEditing())return;
  const total=$('#quote-running-totals');if(total)total.innerHTML=quotePricingHTML();
  for(const o of currentJob().openings){const el=document.querySelector(`[data-price-opening="${o.id}"]`);if(el)el.textContent=invalidFields.size&&o.id===currentOpening()?.id?'Check measurements':money(openingPrice(o,remoteContext.record).lineTotal);}
}
function remoteEditorPage(){
  const j=currentJob(),isQuote=remoteContext.kind==='quote',editable=isQuote&&remoteContext.record.status!=='ordered';
  return `<div class="page-heading"><div><div class="eyebrow">${h(j.number)} · SHUTTERSMART · ${isQuote?'1 · LINE ITEMS':'ORDER'}</div><h1>${isQuote?'Build quote':h(j.name)}</h1><p class="subheading">${h(j.name)} · ${h(j.customer)}</p></div><div class="btn-row">${editable?btn('Save quote','remote-save')+btn('Review proposal →','remote-back',null,'primary'):btn('Back to '+(isQuote?'quote':'order'),'remote-back')}${editable?'':!isQuote?btn('Send to shop','send-shop','arrow')+btn('Download PDF','pdf','download','primary'):''}</div></div><p class="remote-notice">${editable?'Add each opening with its measurements and frame options, then review pricing and the client proposal. Cut sheets are created from the sold order.':'These specifications are preserved from the accepted quote.'}</p><div id="remote-error" class="field-error" role="alert"></div>${editable?`<div class="tabs"><button class="tab ${tab==='openings'?'active':''}" data-tab="openings">Openings</button></div>${openingWorkspace()}<section id="quote-running-totals" class="quote-running-totals" aria-label="Quote pricing">${quotePricingHTML()}</section>`:previewPage()}`;
}
async function saveRemote(back=false){
  if(remoteSaving)return;
  if(!remoteContext.dirty){if(back)location.href='/contacts.html#'+remoteContext.kind+'/'+remoteContext.record.id;return;}
  if(invalidFields.size)return toast('Correct the highlighted measurements before saving.');
  remoteSaving=true;const el=$('#remote-error');if(el)el.textContent='';
  document.querySelectorAll('[data-action="remote-save"],[data-action="remote-back"]').forEach(b=>b.disabled=true);
  try{
    const submitted=structuredClone(currentJob().openings);
    const {quote}=await shopRequest('quote-save',{id:remoteContext.record.id,version:remoteContext.record.version,fields:{openings:submitted,status:'draft'}});
    remoteContext.record=quote;remoteContext.dirty=JSON.stringify(submitted)!==JSON.stringify(currentJob().openings);save(false);
    if(back&&!remoteContext.dirty)location.href='/contacts.html#quote/'+quote.id;else toast(remoteContext.dirty?'Snapshot saved. Save the remaining changes before leaving.':'Openings saved to quote.');
  }catch(e){if(el)el.textContent=e.message;else toast(e.message);}
  finally{remoteSaving=false;document.querySelectorAll('[data-action="remote-save"],[data-action="remote-back"]').forEach(b=>b.disabled=false);}
}
async function loadRemote(){
  $('#app').innerHTML='<main class="content"><p>Loading saved opening specifications…</p></main>';
  try{
    const {record,contact}=await shopRequest('sales-get',{kind:remoteKind,id:remoteParams.get(remoteKind)});
    if(!supportsCutSheets(record))throw new Error(CUT_SHEETS_ONLY+' Open this product from Contacts & quotes.');
    remoteContext={kind:remoteKind,record,dirty:false};
    const job={productId:productId(record),id:record.id,name:record.name,number:record.number,customer:[contact.firstName,contact.lastName].filter(Boolean).join(' ').slice(0,120),notes:'',due:'',archived:false,sample:false,openings:structuredClone(record.openings)};
    state={...state,jobs:[job]};activeJob=job.id;activeOpening=null;view='editor';tab=remoteKind==='quote'&&record.status!=='ordered'?'openings':'preview';render();
    document.title=record.number+' · '+(remoteKind==='quote'?'Quote openings':'Order cut sheets');
  }catch(e){$('#app').innerHTML=`<main class="content"><h1>Openings unavailable</h1><p class="subheading">${h(e.message)}</p><a class="btn" href="/contacts.html">Back to contacts & quotes</a></main>`;}
}
window.addEventListener('beforeunload',e=>{if(remoteContext?.dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&remoteContext?.dirty){e.preventDefault();toast('Save your opening changes before leaving.');}});
if(remoteKind)await loadRemote();else{save(false);render();}
